 {showHistory&&<section className="libraryHistory"><div className="libraryInventoryHead"><div><small>DENETİM İZİ</small><h3>Son Kütüphane İşlemleri</h3></div><b>{audit.length} kayıt</b></div><div className="libraryHistoryList">{audit.map(a=>{const b=books.find(x=>x.id===a.book_id),cp=copies.find(x=>x.id===a.copy_id),actor=actors.find(x=>x.id===a.actor_id),label=({loan_checkout:'Ödünç verildi',loan_return:'İade alındı',copy_status:'Nüsha durumu değişti',copy_updated:'Nüsha güncellendi',reading_recorded:'Okuma takibi kaydedildi',inventory_closed:'Envanter sayımı kapatıldı',reservation_created:'Rezervasyon oluşturuldu',reservation_ready:'Rezervasyon hazırlandı',reservation_cancelled:'Rezervasyon iptal edildi',book_updated:'Eser bilgileri güncellendi',book_deactivated:'Eser pasife alındı',book_archived:'Eser arşivlendi',book_restored:'Eser kataloğa geri alındı',copy_added:'Yeni nüsha eklendi'}[a.action]||a.action);return <div key={a.id}><span><b>{label}</b><small>{b?.title||'Eser'}{cp?.asset_code?' · '+cp.asset_code:''}</small></span><em>{actor?.full_name||'Sistem'} · {new Date(a.created_at).toLocaleString('tr-TR')}</em></div>})}{!audit.length&&<p>Henüz görüntülenecek işlem kaydı bulunmuyor.</p>}</div></section>}
 <section className="libraryPanel"><div className="libraryToolbar"><div><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Kitap, yazar, ISBN veya kategori ara..."/></div><div className="libraryCatalogTools"><b>{filtered.length} eser</b>{canReportExport&&<><button type="button" onClick={exportCatalogExcel}>Excel</button><button type="button" onClick={exportCatalogWord}>Word</button><button type="button" onClick={printCatalog}>PDF / Yazdır</button></>}</div></div>
 <div className="libraryGrid">{filtered.map(b=>{const bc=copies.filter(c=>c.book_id===b.id),avail=bc.filter(c=>c.status==='available').length;return <article key={b.id}><div className="bookCover">{b.cover_url?<img src={b.cover_url} alt=""/>:<BookOpen size={28}/>}</div><div><small>{b.category||'GENEL'}</small><h3>{b.title}</h3><p>{b.author||'Yazar belirtilmedi'}</p><span>{(()=>{const locs=[...new Set(bc.map(cp=>shelves.find(s=>s.id===cp.shelf_id)?.code).filter(Boolean))];return locs.length?'Raf: '+locs.join(', '):(b.shelf_location||'Raf belirtilmedi')})()}</span>{(()=>{const vh=volumeHealth(b);return vh&&<div className={vh.complete?'libraryVolumeHealth ok':'libraryVolumeHealth warn'}><b>{vh.complete?'Cilt takımları tam':'Cilt / takım kontrolü gerekli'}</b><small>{vh.complete?vh.setCount+' takım · '+b.volume_count+' cilt eksiksiz':vh.issues.map(x=>'Takım '+x.set+(x.missing.length?' · Eksik cilt: '+x.missing.join(', '):'')+(x.dup.length?' · Mükerrer: '+x.dup.join(', '):'')).join(' | ')}</small></div>})()}<footer><b>{avail} rafta</b><em>{bc.length} nüsha{(b.volume_count||1)>1?' · '+b.volume_count+' cilt':''}</em>{canUpdate&&<><button type="button" onClick={()=>setCopyBook(copyBook===b.id?null:b.id)}>Kopyalar</button><button type="button" onClick={()=>setEditBook(b)}><Pencil size={13}/> Düzenle</button><button type="button" onClick={()=>setAddCopyBook(b)}><Plus size={13}/> Nüsha</button><button type="button" className="libraryDanger" onClick={()=>deactivateBook(b.id)}><Archive size={13}/> Kütüphaneden Çıkar</button></>}</footer>{copyBook===b.id&&<div className="libraryCopies">{bc.map(cp=><div key={cp.id}><code>{cp.asset_code}{(b.volume_count||1)>1?' · Cilt '+cp.volume_no+' · Takım '+cp.set_no:''}</code><select value={cp.shelf_id||''} onChange={e=>assignShelf(cp.id,e.target.value)}><option value="">Raf seçilmedi</option>{shelves.map(s=><option key={s.id} value={s.id}>{s.code}</option>)}</select><select value={cp.status} disabled={cp.status==='loaned'} onChange={e=>setCopyStatus(cp.id,e.target.value)}><option value="available">Rafta</option><option value="lost">Kayıp</option><option value="damaged">Hasarlı</option><option value="maintenance">Bakımda</option></select></div>)}</div>}</div></article>})}{!filtered.length&&<div className="libraryEmpty">Henüz katalog kaydı bulunmuyor.</div>}</div></section>
 {returningLoan&&<div className="libraryModal"><form className="libraryAddForm libraryReturnForm" onSubmit={e=>returnLoan(e,returningLoan.id)}><h3>Kitap İadesi</h3><p>{(()=>{const cp=copies.find(x=>x.id===returningLoan.copy_id),b=books.find(x=>x.id===cp?.book_id);return (b?.title||'Kitap')+(cp?.asset_code?' · '+cp.asset_code:'')})()}</p><select name="condition" defaultValue="good"><option value="good">Sağlam / Normal</option><option value="damaged">Hasarlı</option></select><textarea name="note" placeholder="İade notu (isteğe bağlı)"/><div><button type="button" onClick={()=>setReturningLoan(null)}>Vazgeç</button><button><RotateCcw size={14}/> İadeyi Tamamla</button></div></form></div>}
 {editCopy&&<div className="libraryModal"><form className="libraryAddForm" onSubmit={updateCopy}><h3>Nüsha / Demirbaş Bilgileri</h3><input name="asset" defaultValue={editCopy.asset_code||''} placeholder="Demirbaş kodu" required/><input name="barcode" defaultValue={editCopy.barcode||''} placeholder="Barkod"/><input name="acquired" type="date" defaultValue={editCopy.acquired_at||''}/>{(()=>{const b=books.find(x=>x.id===editCopy.book_id);return <><label>Cilt No<input name="volume" type="number" min="1" max={b?.volume_count||1} defaultValue={editCopy.volume_no||1}/></label><label>Takım / Set No<input name="set" type="number" min="1" max="1000" defaultValue={editCopy.set_no||1}/></label></>})()}<textarea name="note" defaultValue={editCopy.condition_note||''} placeholder="Kondisyon / envanter notu"/><div><button type="button" onClick={()=>setEditCopy(null)}>Vazgeç</button><button>Kaydet</button></div></form></div>}
 {editBook&&<div className="libraryModal"><form className="libraryAddForm libraryEditForm" onSubmit={updateBook}><h3>Eser Bilgilerini Düzenle</h3><input name="title" defaultValue={editBook.title||''} placeholder="Eser adı" required/><input name="author" defaultValue={editBook.author||''} placeholder="Yazar"/><input name="publisher" defaultValue={editBook.publisher||''} placeholder="Yayınevi"/><input name="isbn" defaultValue={editBook.isbn||''} placeholder="ISBN"/><input name="category" defaultValue={editBook.category||''} placeholder="Kategori"/><input name="year" type="number" min="1000" max={new Date().getFullYear()+1} defaultValue={editBook.publication_year||''} placeholder="Yayın yılı"/><p className="libraryLocationHint">Fizikî raf konumu nüsha bazında <b>Yerleşim / Raflar</b> bölümünden yönetilir.{editBook.shelf_location?' Eski konum kaydı: '+editBook.shelf_location:''}</p><input type="hidden" name="shelf" value={editBook.shelf_location||''}/><label>Cilt Sayısı<input name="volume_count" type="number" min="1" max="100" defaultValue={editBook.volume_count||1}/></label><input name="cover" defaultValue={editBook.cover_url||''} placeholder="Kapak görseli URL"/><textarea name="description" defaultValue={editBook.description||''} placeholder="Açıklama"/><div><button type="button" onClick={()=>setEditBook(null)}>Vazgeç</button><button>Kaydet</button></div></form></div>}
 {addCopyBook&&<div className="libraryModal"><form className="libraryAddForm" onSubmit={addCopy}><h3>{addCopyBook.title} · Yeni Nüsha</h3>{(addCopyBook.volume_count||1)>1&&<select name="volume" required defaultValue="1">{Array.from({length:addCopyBook.volume_count},(_,i)=><option key={i+1} value={i+1}>Cilt {i+1}</option>)}</select>}{(addCopyBook.volume_count||1)<=1&&<input type="hidden" name="volume" value="1"/>}<input name="set" type="number" min="1" defaultValue="1" placeholder="Takım / Set No" required/><input name="asset" placeholder="Demirbaş kodu" required/><input name="barcode" placeholder="Barkod (isteğe bağlı)"/><input name="acquired" type="date" defaultValue={new Date().toISOString().slice(0,10)}/><textarea name="note" placeholder="Kondisyon / envanter notu"/><div><button type="button" onClick={()=>setAddCopyBook(null)}>Vazgeç</button><button>Nüshayı Ekle</button></div></form></div>}
